#include <iostream>
#include <vector>

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

// Step 1: Inorder traversal to fill sorted array
void storeInorder(Node* root, std::vector<int>& arr) {
    if (root == nullptr) return;
    storeInorder(root->left, arr);
    arr.push_back(root->data);
    storeInorder(root->right, arr);
}

// Step 2: Merge two sorted arrays
std::vector<int> mergeArrays(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> merged;
    int i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] < b[j]) {
            merged.push_back(a[i++]);
        } else {
            merged.push_back(b[j++]);
        }
    }
    while (i < a.size()) merged.push_back(a[i++]);
    while (j < b.size()) merged.push_back(b[j++]);
    return merged;
}

// Step 3: Build balanced BST from sorted array
Node* buildBalancedBST(const std::vector<int>& arr, int start, int end) {
    if (start > end) return nullptr;

    int mid = start + (end - start) / 2;
    Node* root = new Node(arr[mid]);

    root->left = buildBalancedBST(arr, start, mid - 1);
    root->right = buildBalancedBST(arr, mid + 1, end);

    return root;
}

// Combined function
Node* mergeBSTs(Node* root1, Node* root2) {
    std::vector<int> arr1, arr2;
    storeInorder(root1, arr1);
    storeInorder(root2, arr2);

    std::vector<int> merged = mergeArrays(arr1, arr2);
    return buildBalancedBST(merged, 0, merged.size() - 1);
}
